import torch.nn as nn

# MultiHeadAttention is the module from the previous section.


class EncoderLayer(nn.Module):
    def __init__(self, d_model=512, h=8, d_ff=2048, p_drop=0.1):
        super().__init__()
        self.attn = MultiHeadAttention(d_model, h)
        self.ff = nn.Sequential(
            nn.Linear(d_model, d_ff), nn.ReLU(), nn.Linear(d_ff, d_model)
        )
        self.norm1, self.norm2 = nn.LayerNorm(d_model), nn.LayerNorm(d_model)
        self.drop = nn.Dropout(p_drop)

    def forward(self, x, mask=None):
        # x: [B, T, d_model]; each sublayer is LayerNorm(x + Sublayer(x))
        x = self.norm1(x + self.drop(self.attn(x, x, x, mask)))
        return self.norm2(x + self.drop(self.ff(x)))
